<script lang="ts">
 import {onMount,tick} from 'svelte'
 import {branchPayload,validateBranch} from '../../studies/expansion.mjs'
 const uid=$props.id()
 let mounted=$state(false), name=$state('Maya Chen'),delivery=$state('post'),address=$state('12 Example Lane'),date=$state('1990-06-15'),quantity=$state('2'),booking=$state('2027-03-09'), end=$state('2027-03-11'), zone=$state('Asia/Taipei'),step=$state('entry'),errors=$state<Record<string,string>>({}),message=$state(''),fail=$state(true)
 const draft=$derived({name,delivery,address,date,quantity})
 onMount(()=>{mounted=true})
 async function review(){errors=validateBranch(draft);if(end<=booking)errors.booking='Choose a checkout day after the arrival date.';if(Object.keys(errors).length){await tick();document.getElementById(`${uid}-errors`)?.focus()}else{step='review';await tick();document.getElementById(`${uid}-review`)?.focus()}}
 async function edit(){step='entry';await tick();document.getElementById(`${uid}-name`)?.focus()}
 async function submit(){if(fail){fail=false;message='Simulated failure. Reviewed values are retained.'}else{step='complete';message='Confirmed locally; nothing sent.';await tick();document.getElementById(`${uid}-review`)?.focus()}}
</script>
<section class="task-study" data-study="branch" aria-label="Dates, quantities and a changing branch"><p>Fictional request. Remembered dates use YYYY-MM-DD; bookings are fixed March 2027 dates in Asia/Taipei. No external submission.</p>
<fieldset disabled={!mounted}><legend class="study-sr">Branching request</legend>
{#if step==='entry'}<form novalidate onsubmit={e=>{e.preventDefault();review()}}>
{#if Object.keys(errors).length}<div class="study-summary" id={`${uid}-errors`} tabindex="-1"><p>Correct the marked fields:</p><ul>{#each Object.entries(errors) as [key,error]}<li><a href={`#${uid}-${key}`} onclick={()=>document.getElementById(`${uid}-${key}`)?.focus()}>{error}</a></li>{/each}</ul></div>{/if}
<label class="study-field">Name<input id={`${uid}-name`} class="input" autocomplete="name" bind:value={name} aria-invalid={!!errors.name}/></label>
<label class="study-field">Remembered date · YYYY-MM-DD<input id={`${uid}-date`} class="input" bind:value={date} aria-invalid={!!errors.date} aria-describedby={`${uid}-date-help`}/><small id={`${uid}-date-help`}>{errors.date||'Civil date; changing a display zone must not change it.'}</small></label>
<label class="study-field">Exact quantity · 1 to 20<input id={`${uid}-quantity`} class="input" inputmode="numeric" bind:value={quantity} aria-invalid={!!errors.quantity} aria-describedby={`${uid}-quantity-help`}/><small id={`${uid}-quantity-help`}>{errors.quantity||'Whole items. Invalid input remains available for correction.'}</small></label>
<label class="study-field">Delivery<select class="select" bind:value={delivery}><option value="post">Post · address required</option><option value="collect">Collect · no address submitted</option></select></label>
{#if delivery==='post'}<label class="study-field">Postal address<input id={`${uid}-address`} class="input" autocomplete="street-address" bind:value={address} aria-invalid={!!errors.address}/>{#if errors.address}<small>{errors.address}</small>{/if}</label>{/if}
<label class="study-field">Available appointment · Asia/Taipei<select id={`${uid}-booking`} class="select" bind:value={booking} aria-invalid={!!errors.booking}><option value="2027-03-09">9 March 2027, 10:00</option><option disabled value="2027-03-10">10 March 2027 · unavailable</option><option value="2027-03-11">11 March 2027, 10:00</option></select></label><label class="study-field">Range end · checkout day, excluded<select class="select" bind:value={end}><option value="2027-03-11">11 March 2027</option><option value="2027-03-12">12 March 2027</option></select></label><label class="study-field">Display time zone<select class="select" bind:value={zone}><option>Asia/Taipei</option><option>UTC</option></select></label><p>Same appointment instant: {booking} {zone==='UTC'?'02:00 UTC':'10:00 Asia/Taipei'}. The remembered date remains {date}.</p><button class="btn btn-primary" type="submit">Review branch request</button></form>
{:else}<h4 tabindex="-1" id={`${uid}-review`}>{step==='complete'?'Request complete':'Review active values'}</h4><dl class="study-review">{#each Object.entries(branchPayload(draft)) as [key,value]}<dt>{key}</dt><dd>{value}</dd>{/each}<dt>Appointment</dt><dd>{booking} {zone==='UTC'?'02:00 UTC':'10:00 Asia/Taipei'}</dd><dt>Checkout day (excluded)</dt><dd>{end}</dd></dl>{#if step!=='complete'}<div class="study-actions"><button class="btn" onclick={edit}>Change branch details</button><button class="btn btn-primary" onclick={submit}>Submit branch request</button></div>{/if}{/if}
<p role="status">{message}</p><button class="btn" onclick={()=>{name='Maya Chen';delivery='post';address='12 Example Lane';date='1990-06-15';quantity='2';booking='2027-03-09';end='2027-03-11';zone='Asia/Taipei';step='entry';errors={};message='';fail=true}}>Reset branch request</button></fieldset><noscript>Initial values remain visible. Review and submission require JavaScript.</noscript></section>
